import {analyze,formatMetric,TIERS} from './metrics.mjs';
const $=s=>document.querySelector(s),canvas=$('#face'),ctx=canvas.getContext('2d');
let image=null,points=null,report=null,mode='proportions',tab='overview',selected=null,isSample=true,model=null,engine=null,working=false;
function status(message,error=false){$('#status').textContent=message;$('#status').classList.toggle('error',error)}
function busy(on,message='Mapping facial landmarks…'){working=on;$('#busy').hidden=!on;$('#busy-text').textContent=message;['#upload-btn','#sample-btn','#empty-sample'].forEach(s=>{if($(s))$(s).disabled=on})}
async function getModel(){if(model)return model;busy(true,'Loading the face analysis engine…');engine=await import('./vendor/vision_bundle.mjs');const files=await engine.FilesetResolver.forVisionTasks('./vendor');model=await engine.FaceLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'./vendor/face_landmarker.task',delegate:'CPU'},runningMode:'IMAGE',numFaces:2,minFaceDetectionConfidence:.6,minFacePresenceConfidence:.6,minTrackingConfidence:.6});return model}
function draw(){if(!image)return;canvas.width=image.width;canvas.height=image.height;ctx.drawImage(image,0,0);if(!points||mode==='none')return;const w=canvas.width,h=canvas.height,scale=Math.max(w,h)/800;ctx.lineWidth=1.15*scale;ctx.strokeStyle='#77edc0';ctx.fillStyle='#bfffd7';
 function segment(a,b,dashed=false){ctx.setLineDash(dashed?[6*scale,5*scale]:[]);ctx.beginPath();ctx.moveTo(points[a].x*w,points[a].y*h);ctx.lineTo(points[b].x*w,points[b].y*h);ctx.stroke()}
 if(mode==='mesh'){ctx.globalAlpha=.35;ctx.lineWidth=.65*scale;for(const edge of engine.FaceLandmarker.FACE_LANDMARKS_TESSELATION)segment(edge.start,edge.end);ctx.globalAlpha=1}
 if(mode==='points'){for(const p of points){ctx.beginPath();ctx.arc(p.x*w,p.y*h,1.3*scale,0,Math.PI*2);ctx.fill()}}
 if(mode==='proportions'){let segments=selected?report.features.find(f=>f.id===selected)?.segments:null;segments=segments||[[10,152],[234,454],[33,133],[362,263],[133,362],[98,327],[61,291],[172,397]];for(const [a,b]of segments){segment(a,b,a===10);for(const i of[a,b]){ctx.beginPath();ctx.arc(points[i].x*w,points[i].y*h,2.5*scale,0,Math.PI*2);ctx.fill()}}ctx.setLineDash([]);if(!selected){const xs=points.map(p=>p.x*w),left=Math.min(...xs)-20*scale,right=Math.max(...xs)+20*scale;ctx.globalAlpha=.6;for(const i of[168,2,152]){ctx.beginPath();ctx.moveTo(left,points[i].y*h);ctx.lineTo(right,points[i].y*h);ctx.stroke()}ctx.globalAlpha=1}}
 ctx.setLineDash([]);
}
function row(m){return `<div class="metric-row ${selected===m.id?'selected':''}"><div class="metric-top"><button data-metric="${m.id}" title="Show this measurement on the face">${m.name}</button><span class="metric-value">${formatMetric(m)}</span></div><p>${m.detail}</p></div>`}
function render(){if(!report)return;const heading=isSample?'Example analysis':'Your analysis';$('#report-badge').textContent=isSample?'EXAMPLE RESULTS':'PHOTO ANALYZED';const warnings=report.warnings.length?report.warnings.join(' '):'Capture check: no strong head turn or roll flagged. Perspective and lighting can still affect results.';
 if(tab==='overview')$('#report-body').innerHTML=`<div class="result-intro"><div><span class="label">${heading} · ${report.landmarkCount} landmarks</span><h3>The proportions, mapped.</h3><p>Select any measurement to highlight its landmarks on the photo.</p></div></div><div class="quality">${warnings}</div>${['eyeSpacing','tiltLeft','tiltRight','noseRatio','lowerFace'].map(id=>row(report.features.find(m=>m.id===id))).join('')}<div class="actions"><button class="text-button" data-goto="measurements">All measurements →</button><button class="text-button" data-goto="scale">View PSL estimate →</button></div><p class="note">2D estimates from this photograph. These measurements describe proportions, not health, character, or an objective standard of beauty.</p>`;
 if(tab==='measurements')$('#report-body').innerHTML=`<h3 class="metric-heading">Landmark measurements</h3><p class="note">Click a name to see exactly which points are used. Angles are corrected for ${report.roll.toFixed(1)}° of image-plane head roll.</p>${report.features.map(row).join('')}<div class="actions"><button class="text-button" id="download-image">Download annotated photo ↗</button></div>`;
 if(tab==='scale')$('#report-body').innerHTML=`<div class="result-intro"><div><span class="label">${heading} · illustrative heuristic</span><h3>${report.tier.name} <span class="label">${report.tier.full===report.tier.name?'':report.tier.full}</span></h3><p>Entertainment estimate. No validated accuracy, percentile, or universal tier mapping.</p></div><div class="score-number">${report.score.toFixed(1)}<small> / 8</small></div></div><p class="note">PSL is an informal online appearance scale. This app uses the following custom bands; other communities use different boundaries.</p>${TIERS.map(t=>`<div class="scale-row ${report.tier.name===t.name?'current':''}"><strong>${t.name}</strong><span>${t.full}</span><span>${t.min}–${t.max}</span></div>`).join('')}<details class="note"><summary>See the exact calculation</summary><p>Five ratios receive equal weight. For each: closeness = max(0, 1 − |measured − reference| / tolerance). The estimate is 8 × mean closeness. Reference / tolerance: facial width-to-height 0.78 / 0.25; eye spacing 1.00 / 0.60; nose-to-mouth 0.65 / 0.50; lower-face share 0.36 / 0.20; mouth-to-face 0.38 / 0.20. These references are illustrative choices, not scientifically established ideals. Symmetry, skin, and tilt do not affect this estimate.</p></details><p class="note">A different formula or photo may produce a different tier. The score cannot tell you how attractive people will find you.</p>`;
 $('#report-body').querySelectorAll('[data-metric]').forEach(b=>b.onclick=()=>{selected=selected===b.dataset.metric?null:b.dataset.metric;setMode('proportions');render()});$('#report-body').querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>setTab(b.dataset.goto));if($('#download-image'))$('#download-image').onclick=()=>{canvas.toBlob(blob=>save(blob,'forma-annotated.png'),'image/png')};
}
function setTab(value){tab=value;document.querySelectorAll('[data-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.tab===tab));b.tabIndex=b.dataset.tab===tab?0:-1});$('#report-body').setAttribute('aria-labelledby',`tab-${tab}`);render()}
function setMode(value){mode=value;document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('selected',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode))});draw()}
async function loadImage(url){const img=new Image();img.src=url;await img.decode();const max=1600,ratio=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const temp=document.createElement('canvas');temp.width=Math.round(img.naturalWidth*ratio);temp.height=Math.round(img.naturalHeight*ratio);temp.getContext('2d').drawImage(img,0,0,temp.width,temp.height);const bitmap=await createImageBitmap(temp);return bitmap}
async function run(url,sample){if(working)return;busy(true);report=null;points=null;selected=null;$('#export').disabled=true;try{const next=await loadImage(url);if(image)image.close();image=next;isSample=sample;$('#photo-label').textContent=sample?'Example portrait':'Your portrait';$('#stage-tag').textContent=sample?'SAMPLE PHOTO · NOT YOUR RESULTS':'YOUR PHOTO · PROCESSED LOCALLY';$('#photo-size').textContent=`${image.width} × ${image.height} PX`;$('#landmark-count').textContent='Detecting landmarks…';draw();const landmarker=await getModel();$('#busy-text').textContent='Measuring facial proportions…';await new Promise(r=>setTimeout(r,30));const result=landmarker.detect(image);if(result.faceLandmarks.length===0)throw Error('No face found. Try a clear, front-facing photo in even light.');if(result.faceLandmarks.length>1)throw Error('More than one face found. Please crop the photo to one person.');points=result.faceLandmarks[0];report=analyze(points,image.width,image.height);$('#landmark-count').textContent=`${points.length} landmarks detected`;$('#export').disabled=false;draw();render();status(sample?'Example ready. Upload your own photo to analyze it.':'Analysis complete. Your photo stayed on this device.')}catch(e){points=null;report=null;draw();$('#report-badge').textContent='TRY ANOTHER PHOTO';$('#landmark-count').textContent='Analysis unavailable';$('#report-body').innerHTML='<div class="empty"><h3>Let’s try another photo.</h3><p>Use a sharp portrait with one visible face looking straight ahead, then upload again.</p></div>';status(e.message||'Analysis failed. Reload the page and try again.',true)}finally{busy(false);if(url.startsWith('blob:'))URL.revokeObjectURL(url)}}
async function upload(file){if(!file||working)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status('Choose a JPG, PNG or WebP image.',true);return}if(file.size>15*1024*1024){status('Image is too large. Choose a photo under 15 MB.',true);return}await run(URL.createObjectURL(file),false)}
function save(blob,name){if(!blob)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('#upload-btn').onclick=()=>$('#upload').click();$('#upload').onchange=async e=>{await upload(e.target.files[0]);e.target.value=''};$('#sample-btn').onclick=$('#empty-sample').onclick=()=>run('./assets/sample.jpg',true);document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{selected=null;setMode(b.dataset.mode)});document.querySelectorAll('[data-tab]').forEach(b=>{b.onclick=()=>setTab(b.dataset.tab);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const items=[...document.querySelectorAll('[data-tab]')],i=items.indexOf(b),next=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;items[next].focus();setTab(items[next].dataset.tab)}});
const drop=$('#drop-zone');for(const type of['dragenter','dragover'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.add('dragging')});for(const type of['dragleave','drop'])drop.addEventListener(type,e=>{e.preventDefault();drop.classList.remove('dragging')});drop.addEventListener('drop',e=>upload(e.dataTransfer.files[0]));window.addEventListener('dragover',e=>e.preventDefault());window.addEventListener('drop',e=>e.preventDefault());
$('#export').onclick=()=>{if(!report)return;const {features,score,tier,warnings,references,roll,landmarkCount}=report;save(new Blob([JSON.stringify({app:'Forma',sample:isSample,createdAt:new Date().toISOString(),disclaimer:'Unvalidated, subjective geometry heuristic. Not an objective attractiveness rating.',photo:{width:image.width,height:image.height},landmarkCount,headRollDegrees:roll,measurements:features.map(({segments,...m})=>m),psl:{score,outOf:8,tier,references},warnings},null,2)],{type:'application/json'}),'forma-report.json')};
try{image=await loadImage('./assets/sample.jpg');draw()}catch{status('Example image could not load. Upload your own photo to start.',true)}
